/* Real compressed RoPE tail64 -> mode2 quant graph against explicit fusion.
 * Fixed immutable initmode1: A uses legacy APIs, B explicit candidate API.
 * Every measured iteration starts from immutable input via an actual GPU copy;
 * this input producer and OUT copy consumer/dependencies are fixture work.
 * --host-only creates no Metal resources. GPU runs require an exclusive window. */
#include "myds_metal.m"
#include "myds_v41_gpu.c"
#include <errno.h>
#include <inttypes.h>
#include <sys/stat.h>
static const char *rq_shader="bin",*rq_dir;
static unsigned rq_samples=5,rq_reps=32,rq_files;
static int rq_host,rq_missing,rq_notiming;
static void rq_fail(const char *file,int line,const char *expr){fprintf(stderr,"FAIL %s:%d %s\n",file,line,expr);fflush(stdout);fflush(stderr);exit(1);}
