static const uint32_t rq_small[]={0,0x80000000,1,0x80000001,0x00007fff,0x80007fff,0x00008000,0x80008000,0x007fffff,0x807fffff,0x00800000,0x80800000};
struct rq_buf{myds_metal_buffer_t *owner,*view;size_t bytes,offset;};
struct rq_fixture{uint32_t heads,rows,pos,stride;unsigned seed,pattern;struct rq_buf input,rope,ref,refcopy,out,outcopy;};
static uint64_t rq_fnv(const void *p,size_t n){uint64_t h=UINT64_C(14695981039346656037);const uint8_t *b=p;for(size_t i=0;i<n;i++){h^=b[i];h*=UINT64_C(1099511628211);}return h;}
static uint32_t rq_rng(uint32_t i,unsigned s){uint32_t z=i*747796405u+s*2891336453u;z=((z>>((z>>28u)+4u))^z)*277803737u;return (z>>22u)^z;}
static uint32_t rq_bf16(uint32_t u){if((u&0x7f800000u)!=0x7f800000u)u+=0x7fffu+((u>>16u)&1u);return u&0xffff0000u;}
static struct rq_buf rq_alloc(size_t bytes,size_t offset){struct rq_buf b={.bytes=bytes,.offset=offset};RQ_REQUIRE(bytes&&offset>=64);b.owner=myds_metal_buffer_alloc(offset+bytes+64);RQ_REQUIRE(b.owner);memset(myds_metal_buffer_data(b.owner),0xa5,offset+bytes+64);b.view=myds_metal_buffer_sub_view(b.owner,offset,bytes);RQ_REQUIRE(b.view);return b;}
static void rq_guards(struct rq_buf b){const uint8_t *p=myds_metal_buffer_data(b.owner);for(size_t i=0;i<b.offset;i++)RQ_REQUIRE(p[i]==0xa5);for(size_t i=0;i<64;i++)RQ_REQUIRE(p[b.offset+b.bytes+i]==0xa5);}
static void rq_free(struct rq_buf b){rq_guards(b);myds_metal_buffer_free(b.view);myds_metal_buffer_free(b.owner);}
static void rq_fill(struct rq_buf b,unsigned seed,unsigned pattern){uint32_t *x=myds_metal_buffer_data(b.view);for(size_t i=0;i<b.bytes/4;i++){uint32_t u;float f;
 if(pattern==2)u=rq_small[i%12];else if(pattern==3)u=rq_boundary[i%12];else if(pattern==4){const float tie[]={0.0f,-0.0f,0.25f,-0.25f,0.75f,-0.75f,1.25f,-1.25f,1.75f,-1.75f,2.5f,-2.5f,3.5f,-3.5f,5.0f,-5.0f,6.0f,-6.0f};f=tie[i%18];memcpy(&u,&f,4);}else if(pattern==5)u=0;else{f=((int)(rq_rng((uint32_t)i,seed)%2047)-1023)/257.0f;memcpy(&u,&f,4);if(!pattern)u=rq_bf16(u);}x[i]=u;}}
static struct rq_fixture rq_create(uint32_t h,uint32_t rows,uint32_t pos,uint32_t stride,unsigned seed,unsigned pat){struct rq_fixture f={.heads=h,.rows=rows,.pos=pos,.stride=stride,.seed=seed,.pattern=pat};size_t n=(size_t)h*rows*128*4;f.input=rq_alloc(n,80);f.rope=rq_alloc(n,96);f.ref=rq_alloc(n,112);f.out=rq_alloc(n,128);f.refcopy=rq_alloc(n,144);f.outcopy=rq_alloc(n,160);rq_fill(f.input,seed,pat);return f;}
static void rq_destroy(struct rq_fixture *f){rq_free(f->input);rq_free(f->rope);rq_free(f->ref);rq_free(f->refcopy);rq_free(f->out);rq_free(f->outcopy);}
static void rq_policy(unsigned c,unsigned a){myds_metal_set_concurrent((int)c);myds_metal_set_auto_barrier((int)a);}
static void rq_encoder(void){RQ_REQUIRE(g_batch_enc&&g_batch_enc.dispatchType==(myds_metal_get_concurrent()?MTLDispatchTypeConcurrent:MTLDispatchTypeSerial));}
static void rq_copy(struct rq_buf dst,struct rq_buf src){const myds_metal_buffer_t *dep[]={dst.view,src.view};myds_metal_barrier_buffers(dep,2);RQ_REQUIRE(myds_metal_buffer_copy(dst.view,0,src.view,0,src.bytes));myds_metal_barrier_buffers(dep,2);}
static void rq_outjoin(struct rq_buf b){if(!myds_metal_get_auto_barrier())myds_metal_barrier_buffer(b.view);}
static int rq_pair(const struct rq_fixture *f,struct rq_buf out,bool candidate){
 if(candidate){for(uint32_t row=0;row<f->rows;row++){myds_metal_buffer_t *v=myds_metal_buffer_sub_view(out.view,(size_t)row*f->heads*128*4,(size_t)f->heads*128*4);RQ_REQUIRE(v);int ok=myds_v41_gpu_indexer_rope_quant(v,f->heads,f->pos+row*f->stride);myds_metal_buffer_free(v);if(!ok)return 0;}}
 else{if(!myds_v41_gpu_rope_batch_stride(out.view,128,f->heads,f->pos,f->rows,f->stride,true,false))return 0;rq_outjoin(out);if(!myds_v41_gpu_quant(out.view,128,f->heads*f->rows,2))return 0;}rq_outjoin(out);return 1;}
static id<MTLCommandBuffer> rq_graph(const struct rq_fixture *f,struct rq_buf out,struct rq_buf copy,bool cand,unsigned reps){RQ_REQUIRE(myds_metal_begin_batch());id<MTLCommandBuffer> cb=g_batch_cb;for(unsigned i=0;i<reps;i++){rq_copy(out,f->input);RQ_REQUIRE(rq_pair(f,out,cand));rq_copy(copy,out);}rq_encoder();RQ_REQUIRE(myds_metal_commit_batch());RQ_REQUIRE(cb.status==MTLCommandBufferStatusCompleted);return cb;}
static void rq_oracle(struct rq_fixture *f){RQ_REQUIRE(myds_metal_begin_batch());id<MTLCommandBuffer> cb=g_batch_cb;rq_copy(f->rope,f->input);RQ_REQUIRE(myds_v41_gpu_rope_batch_stride(f->rope.view,128,f->heads,f->pos,f->rows,f->stride,true,false));rq_outjoin(f->rope);rq_encoder();RQ_REQUIRE(myds_metal_commit_batch());RQ_REQUIRE(cb.status==MTLCommandBufferStatusCompleted);rq_graph(f,f->ref,f->refcopy,false,1);}
static bool rq_equal(const struct rq_fixture *f,struct rq_buf out,struct rq_buf copy){return !memcmp(myds_metal_buffer_data(f->ref.view),myds_metal_buffer_data(out.view),f->ref.bytes)&&!memcmp(myds_metal_buffer_data(f->ref.view),myds_metal_buffer_data(copy.view),f->ref.bytes)&&!memcmp(myds_metal_buffer_data(f->ref.view),myds_metal_buffer_data(f->refcopy.view),f->ref.bytes);}
static void rq_finite(struct rq_buf b){const uint32_t *p=myds_metal_buffer_data(b.view);for(size_t i=0;i<b.bytes/4;i++)RQ_REQUIRE((p[i]&0x7f800000u)!=0x7f800000u&&p[i]!=0xa5a5a5a5u);rq_guards(b);}
